import type { ReactNode } from "react";
import { House, Settings, Volume2, Wifi } from "lucide-react";
import { expect, fn, type queries, userEvent, within } from "storybook/test";
import type { ComponentMeta } from "vibestack/stories";
import { AskGraceButton } from "./AskGraceButton.tsx";
import { susan as susanPhoto } from "./Avatar.meta.tsx";
import { MailSignInBanner, MailSyncingRow, type MailAppProps, type MailSummary } from "./MailApp.tsx";
import type { MailAccountRow } from "./MailFolderNav.tsx";
import type { MailContact } from "./MailMessageRow.tsx";
import { Rail, RailButton } from "./Rail.tsx";
import { ScreenSlot, TabletScreen } from "./TabletScreen.tsx";
import { Toast } from "./Toast.tsx";

export const onMailScreen = (interact: (canvas: ReturnType<typeof within<typeof queries>>) => Promise<void>) => async ({ canvasElement }: { canvasElement: HTMLElement }) => {
  await interact(within(canvasElement));
  unfocus();
};

const railIcon = { size: 28, strokeWidth: 1.9 };

export const mailScreen = (story: () => ReactNode) => (
  <TabletScreen>
    <Rail
      battery={75}
      time="8:56"
      period="PM"
      date="Fri, Nov 13"
      aria-label="Tablet"
      status={<RailButton icon={<Wifi {...railIcon} />} label="Wi-Fi" />}
      footer={<RailButton icon={<Settings {...railIcon} />} label="Settings" />}
      ask={<AskGraceButton glow="rest" />}
    >
      <RailButton icon={<House {...railIcon} />} label="Home" />
      <RailButton icon={<Volume2 {...railIcon} />} label="Volume" />
    </Rail>
    <ScreenSlot>{story()}</ScreenSlot>
  </TabletScreen>
);

export const unfocus = () => (document.activeElement as HTMLElement | null)?.blur();

export const retriesUnshown =
  (waiting: string, retry: ReturnType<typeof fn>) =>
  async ({ canvasElement }: { canvasElement: HTMLElement }) => {
    const canvas = within(canvasElement);
    await expect(canvas.getByRole<HTMLButtonElement>("button", { name: waiting }).disabled).toBe(true);
    await userEvent.click(canvas.getByRole("button", { name: "Try again" }));
    await expect(retry).toHaveBeenCalled();
    unfocus();
  };

const cross = (
  <svg aria-hidden width="30" height="30" viewBox="0 0 24 24">
    <path d="M9 3h6v6h6v6h-6v6H9v-6H3V9h6z" fill="currentColor" />
  </svg>
);

export const people = {
  susan: { name: "Susan", photo: susanPhoto },
  david: { name: "David", tone: 2 },
  clinic: { name: "Main St Clinic", tone: 1, mark: cross },
  linda: { name: "Linda’s salon", tone: 5 },
  book: { name: "Riverside Book Club", tone: 3 },
  joan: { name: "Joan", tone: 6 },
  security: { name: "Account Security", tone: 4 },
} satisfies Record<string, MailContact>;

export const inbox: MailSummary[] = [
  { id: "susan", from: people.susan, subject: "Photos from Lily’s recital", time: "2:15 PM", unread: true, attachment: true },
  { id: "clinic", from: people.clinic, subject: "Reminder: your appointment tomorrow at 10 am", time: "11:02 AM", unread: true, attachment: true },
  { id: "book", from: people.book, subject: "Our book for December", time: "Yesterday" },
  { id: "scam", from: people.security, subject: "Urgent: confirm your password", time: "Yesterday" },
];

const open = fn();
const folder = fn();
const write = fn();
const retry = fn();
const connect = fn();

export const mailAccounts: MailAccountRow[] = [
  { id: 1, name: "Gmail", colour: 0, unread: 2, needsSignIn: false },
  { id: 2, name: "Outlook", colour: 1, unread: 1, needsSignIn: false },
];
const signIn = fn();
const fixWifi = fn();
const undo = fn();

const tagged: MailSummary[] = [
  ...inbox.slice(0, 2).map((m) => ({ ...m, account: "Gmail" })),
  { id: "outlook-1", from: people.joan, subject: "Lunch on Thursday?", time: "10:40 AM", unread: true, account: "Outlook" },
  ...inbox.slice(2).map((m) => ({ ...m, account: "Gmail" })),
];

export const meta: ComponentMeta<MailAppProps> = {
  args: { folder: "inbox", counts: { inbox: 2 }, messages: inbox, onOpen: open, onSelectFolder: folder, onWrite: write, onClose: fn() },
  examples: {
    "Grace points at what she found": { query: "book", messages: inbox.filter((m) => m.id === "book"), guide: { targetId: "book", kind: "instruction", title: "Tap Riverside Book Club", onClose: fn() } },
    "Nothing found": { query: "Thanksgiving", messages: [] },
    Trash: { folder: "trash", messages: [{ ...inbox[2], id: "book" }] },
    "Two accounts, moved to Trash": {
      counts: { inbox: 3 },
      accounts: mailAccounts,
      messages: tagged.slice(1),
      banners: <MailSyncingRow name="Yahoo" />,
      toast: (
        <Toast placement="screen" onUndo={undo}>
          Moved to Trash
        </Toast>
      ),
    },
    "Offline, with banners": {
      status: "offline",
      onFixWifi: fixWifi,
      accounts: [mailAccounts[0], { ...mailAccounts[1], needsSignIn: true }],
      messages: tagged,
      banners: <MailSignInBanner name="Outlook" others onSignIn={signIn} />,
    },
    Outbox: { folder: "outbox", counts: { inbox: 2, outbox: 1 }, messages: [{ id: "o1", from: people.susan, subject: "Sunday", time: "Just now" }] },
    "No account": { noAccount: true, messages: [], onConnect: connect, onAskGrace: fn() },
    "No account, refused": { noAccount: true, messages: [], onConnect: undefined, onAskGrace: undefined },
    Refused: {
      onWrite: undefined,
      onFixWifi: undefined,
      status: "offline",
      accounts: [mailAccounts[0], { ...mailAccounts[1], needsSignIn: true }],
      messages: tagged,
      banners: <MailSignInBanner name="Outlook" others />,
    },
    "Load failed": { status: "failed", onRetry: retry },
  },
  decorator: mailScreen,
  play: {
    Default: onMailScreen(async (canvas) => {
      await userEvent.click(canvas.getByRole("button", { name: /Riverside Book Club/ }));
      await expect(open).toHaveBeenCalledWith("book");
      await userEvent.click(canvas.getByRole("button", { name: /Sent/ }));
      await expect(folder).toHaveBeenCalledWith("sent");
      await userEvent.click(canvas.getByRole("button", { name: "Write" }));
      await expect(write).toHaveBeenCalled();
    }),
    "No account": async ({ canvasElement }: { canvasElement: HTMLElement }) => {
      const canvas = within(canvasElement);
      await expect(canvas.queryByRole("button", { name: "Write" })).toBeNull();
      await userEvent.click(canvas.getByRole("button", { name: "Connect your email" }));
      await expect(connect).toHaveBeenCalled();
      unfocus();
    },
    "No account, refused": async ({ canvasElement }: { canvasElement: HTMLElement }) => {
      const canvas = within(canvasElement);
      await expect(canvas.getByRole("button", { name: "Connect your email" })).toBeDisabled();
      await expect(canvas.queryByRole("button", { name: "Ask Grace to help" })).toBeNull();
    },
    Refused: async ({ canvasElement }: { canvasElement: HTMLElement }) => {
      const canvas = within(canvasElement);
      await expect(canvas.getByRole("button", { name: "Write" })).toBeDisabled();
      await expect(canvas.getByText("No internet right now")).toBeTruthy();
      await expect(canvas.getByText("Outlook needs you to sign in again")).toBeTruthy();
      await expect(canvas.queryByRole("button", { name: "Fix Wi-Fi" })).toBeNull();
      await expect(canvas.queryByRole("button", { name: "Sign in again" })).toBeNull();
    },
    "Offline, with banners": onMailScreen(async (canvas) => {
      await userEvent.click(canvas.getByRole("button", { name: "Sign in again" }));
      await expect(signIn).toHaveBeenCalled();
      await userEvent.click(canvas.getByRole("button", { name: "Fix Wi-Fi" }));
      await expect(fixWifi).toHaveBeenCalled();
    }),
    "Two accounts, moved to Trash": onMailScreen(async (canvas) => {
      await userEvent.click(canvas.getByRole("button", { name: "Undo" }));
      await expect(undo).toHaveBeenCalled();
    }),
    "Load failed": async ({ canvasElement }: { canvasElement: HTMLElement }) => {
      const canvas = within(canvasElement);
      await expect(canvas.getByRole("button", { name: /Riverside Book Club/ })).toBeTruthy();
      await userEvent.click(canvas.getByRole("button", { name: "Try again" }));
      await expect(retry).toHaveBeenCalled();
      unfocus();
    },
  },
};

